  start();step(100);install({R07:1});check('acquiring rooted after earlier standing starts from zero',near(s().contracts.stationarySeconds,0)&&near(s().contracts.stance,1),s().contracts);step(19);check('rooted before1second stays neutral',s().contracts.stationarySeconds<1&&near(s().contracts.stance,1),s().contracts);step();check('rooted exactly1effective second receives1.4',near(s().contracts.stationarySeconds,1)&&near(s().contracts.stance,1.4),s().contracts);
