  start({R07:1});step(25);const beforeCamera=s().contracts;pos(a.cat,500,800);a.cameras.main.setScroll(130,200);step();check('camera scroll and external reposition with no autonomy do not break rooted',!s().contracts.moving&&s().contracts.stationarySeconds>=beforeCamera.stationarySeconds&&near(s().contracts.stance,1.4),s().contracts);
